const $=id=>document.getElementById(id);
let brief=null, blocks=[], prompt='', imageBusy=false;
const api=(window.STORY_KIT_API_URL||'').replace(/\/$/,'');
const value=id=>$(id).value.trim();
document.querySelectorAll('[data-view]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b===btn));$('toolView').style.display=btn.dataset.view==='tool'?'block':'none';$('caseView').classList.toggle('show',btn.dataset.view==='case');}));
function build(){
 brief=Object.fromEntries(['piece','material','inspiration','audience','tier','detail','benefit','tone','goal','visual','palette'].map(id=>[id,value(id)]));
 const b=brief, reason=b.benefit||'express a personal connection to the design', details=b.detail||'Add confirmed dimensions, setting details, and finish before publishing.', cta=b.goal==='Consultation inquiries'?'Book a design consultation':b.goal==='Product discovery'?'Explore the piece':'Discover the collection';
 const voices={'Refined and editorial':`${b.piece}. A study in material and meaning.`,'Warm and personal':`A little of your story, held in ${b.material}.`,'Bold and expressive':`Make your mark with ${b.piece}.`};
 const headline=voices[b.tone];
 blocks=[
 ['Positioning & customer motivation',`Audience: ${b.audience}\nPrice positioning: ${b.tier}\nMotivation to explore: ${reason}.\nProposed positioning: ${b.piece} connects ${b.inspiration} with ${b.material} for this audience. Validate this direction with customer feedback.`],
 ['Product narrative',`${headline}\n\nInspired by ${b.inspiration}, ${b.piece} brings that idea into ${b.material}. ${b.detail?`Design notes: ${b.detail}.`:'The material and inspiration form the starting point of its identity.'}\n\nFor the ${b.audience.toLowerCase()}, the story centers on the desire to ${reason}. Use imagery and confirmed specifications to make that connection tangible.`],
 ['Product page structure',`Headline: ${headline}\nOpening: Meet ${b.piece}, an exploration of ${b.inspiration} in ${b.material}.\nDesign details: ${details}\nCustomer relevance: An invitation to ${reason}.\nCall to action: ${cta}.\nBefore launch: add verified price, sizing, delivery, returns, and care information.`],
 ['Campaign concept',`Creative theme: ${b.inspiration}\nGoal: ${b.goal}\nVoice: ${b.tone}\nCentral message: ${headline}\nStory sequence: introduce the inspiration, reveal the design details, then invite the customer to explore. Keep the same material and form language across every channel.`],
 ['Social content — three posts',`01 / Inspiration\nThe starting point: ${b.inspiration}. A first look at the idea behind ${b.piece}.\nVisual: an atmospheric detail reflecting the inspiration.\n\n02 / Product reveal\n${headline} Designed in ${b.material}. ${b.detail||'Explore the form and material up close.'}\nVisual: a clear product view.\n\n03 / Invitation\nWhat does it mean to ${reason}? Discover the story behind ${b.piece}. ${cta}.\nVisual: a close-up paired with the campaign headline.`],
 ['Launch email',`Subject A: Introducing ${b.piece}\nSubject B: The inspiration behind ${b.piece}\nPreheader: Explore ${b.inspiration}, expressed in ${b.material}.\n\n${headline}\n\nWe began with ${b.inspiration}. The result is ${b.piece}: a design in ${b.material}, created around the idea of helping you ${reason}.\n\n${b.detail||'Discover the design details and the inspiration behind the piece.'}\n\n${cta} → [add product or consultation link]`],
 ['Visual direction',`Format: ${b.visual}\nPiece: ${b.piece}\nMaterial: ${b.material}\nDesign details: ${details}\nAtmosphere: ${b.palette||'Neutral backdrop, soft directional light, accurate material texture'}\nInspiration: ${b.inspiration}\nKeep jewelry in focus. Leave negative space for campaign copy. Show a concept rather than implying a verified production photograph.`],
 ['Launch sequence & measurement',`Before launch: tease inspiration; track engaged visits and email signups.\nLaunch: publish the product story, reveal post, and email; track product-page visits and email click-through.\nFollow-up: share design details and answer customer questions; track ${b.goal==='Consultation inquiries'?'consultation requests':'add-to-cart actions and purchase conversion where ecommerce tracking exists'}.\nTest: compare the two email subjects using one audience and the same creative. Define the baseline and success threshold before launch. No campaign results are assumed.`],
 ['Review before publishing',`Confirm materials, dimensions, stone specifications, availability, price, and lead time. Add evidence before making sourcing, sustainability, durability, or craftsmanship claims. Replace placeholders and adapt the draft to your brand voice.`]
 ];
 $('outTitle').textContent=b.piece;$('storyBlocks').replaceChildren();
 for(const [heading,body] of blocks){const section=document.createElement('div');section.className='copy-block';const h=document.createElement('h3'),p=document.createElement('p');h.textContent=heading;p.textContent=body;p.contentEditable='true';p.setAttribute('role','textbox');p.setAttribute('aria-label',heading);p.setAttribute('aria-multiline','true');section.append(h,p);$('storyBlocks').append(section);}
 prompt=`Create a ${b.visual.toLowerCase()} of a jewelry concept named ${b.piece}. Materials: ${b.material}. Design specifications: ${b.detail||'interpret the inspiration as a jewelry concept'}. Inspiration: ${b.inspiration}. Audience: ${b.audience}. Positioning: ${b.tier}. Mood: ${b.tone}. Palette and backdrop: ${b.palette||'neutral ivory background with soft directional light'}. Show a single coherent jewelry piece with realistic metal and stone textures, thoughtful scale, and generous negative space. No text, logos, or watermarks. This is an AI concept visualization.`;
 $('imagePrompt').textContent=prompt;$('placeholder').style.display='none';$('output').classList.add('show');$('generatedImage').hidden=true;$('imageDownload').hidden=true;$('copyStatus').textContent='';
}
$('brief').addEventListener('submit',e=>{e.preventDefault();build();});
$('example').addEventListener('click',()=>{const sample={piece:'Tidal Arc Ring',material:'Sterling silver',inspiration:'the curves left by receding ocean currents',detail:'A broad sculptural band with a flowing ridge and satin finish',benefit:'carry a reminder of the coast',palette:'Ivory stone, cool silver reflections, soft side lighting'};Object.entries(sample).forEach(([id,v])=>$(id).value=v);build();});
function fullText(){return `${brief.piece}\n\n`+blocks.map(([h,b])=>`${h.toUpperCase()}\n${b}`).join('\n\n')+'\n\nIMAGE BRIEF\n'+prompt;}
$('copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(fullText());$('copyStatus').textContent='Brief copied.';}catch{$('copyStatus').textContent='Clipboard unavailable. Use Download brief instead.';}});
$('download').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([fullText()],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='jewelry-launch-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
$('print').addEventListener('click',()=>window.print());
async function ready(){if(!api){$('imageStatus').textContent='Image generation is awaiting a connection to the image service. You can build and download your full brief now.';return;}try{const r=await fetch(api+'/health',{signal:AbortSignal.timeout(10000)});const d=await r.json();if(!r.ok||!d.ready)throw Error();$('generate').disabled=false;$('imageStatus').textContent='Image studio connected. Complete your brief, then generate a concept.';}catch{$('imageStatus').textContent='Image studio is unavailable. Your launch brief still works; try images again later.';}}
$('generate').addEventListener('click',async()=>{if(imageBusy)return;if(!$('brief').reportValidity())return;build();imageBusy=true;$('generate').disabled=true;$('imageStatus').textContent='Generating your campaign concept. This may take a few minutes…';try{const r=await fetch(api+'/generate-image',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt}),signal:AbortSignal.timeout(240000)});const d=await r.json();if(!r.ok)throw Error(d.detail||'Image generation failed. Try again.');const imageUrl=d.image_data_url||(d.data?.[0]?.b64_json?'data:image/png;base64,'+d.data[0].b64_json:'');if(!/^data:image\/(png|jpeg|webp);base64,/.test(imageUrl))throw Error('The image service returned an unsupported image.');$('generatedImage').src=imageUrl;$('generatedImage').hidden=false;$('imageDownload').href=imageUrl;$('imageDownload').hidden=false;$('imageStatus').textContent='AI-generated concept ready. Review design details before using it.';}catch(e){$('imageStatus').textContent=e.name==='TimeoutError'?'Generation timed out. Try again shortly.':e.message;}finally{imageBusy=false;$('generate').disabled=false;}});
ready();

$('storyBlocks').addEventListener('input',()=>{document.querySelectorAll('#storyBlocks .copy-block p').forEach((el,n)=>{if(blocks[n])blocks[n][1]=el.textContent;});});
